const catalogById = new Map(requestedCountries.map(country => [country.id, country]));

const countriesAdditional: Country[] = seeds.map(([
  id, iso, continent, capital, currency, language, highlights, interests,
  bestMonths, bestMonthsLabel, seasonalNote, otherMonthsNote, accessNote,
]) => {
  const catalogEntry = catalogById.get(id);
  if (!catalogEntry) throw new Error(`Missing catalog entry for ${id}`);
  const seasonalMonths: SeasonalMonth[] = Array.from({ length: 12 }, (_, index) => {
    const month = (index + 1) as MonthNumber;
    const preferred = bestMonths.includes(month);
    return {
      month,
      rating: preferred ? 'best' : 'fair',
      label: preferred ? 'Preferred climate window' : 'Seasonal trade-offs',
      note: `${preferred ? seasonalNote : otherMonthsNote}${accessNote ? ` ${accessNote}` : ''}`,
    };
  });
  return {
    id,
    name: catalogEntry.name,
    slug: id,
    flag: Array.from(iso.toUpperCase(), char => String.fromCodePoint(127397 + char.charCodeAt(0))).join(''),
    continent,
    capital,
    currency,
    language,
    heroImage: '',
    description: `${catalogEntry.name}: ${highlights.join('; ')}. ${seasonalNote}${accessNote ? ` ${accessNote}` : ''}`,
    poetLine: highlights.join(' · '),
    bestMonths,
    bestMonthsLabel,
    recommendedDuration: 'Depends on route and current access',
    destinations: [],
    seasonalMonths,
    festivals: [],
    foods: [],
    cultureHighlights: highlights,
    travelStyles: interests,
    weather: [],
    tripDurations: [],
    season: bestMonthsLabel,
    famousFor: highlights,
    interests,
    avoid: [otherMonthsNote, accessNote, safetyNote].filter(Boolean).join(' '),
    specialHighlight: `${seasonalNote} ${safetyNote}`,
  };
});

export default countriesAdditional;
